import{_ as i,a0 as l,w as o,s as r,ao as h,I as t,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"我是如何開始踏上 bash 腳本編程之路的？ | LCTT x X-CMD","titleTemplate":false,"description":"我是如何開始踏上 bash 腳本編程之路的？ | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我是如何開始踏上 bash 腳本編程之路的？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我是如何開始踏上 bash 腳本編程之路的？ | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170515 How I got started with bash scripting","title":"我是如何開始踏上 bash 腳本編程之路的？","tag":"201706","desc":""},"relativePath":"201706/20170515 How I got started with bash scripting.md","filePath":"[post].md"}'),d={name:"201706/20170515 How I got started with bash scripting.md"};function g(c,s,u,b,m,k){const n=l("Link");return o(),r("div",null,[s[13]||(s[13]=h(`<h1 id="我是如何開始踏上-bash-腳本編程之路的" tabindex="-1">我是如何開始踏上 bash 腳本編程之路的？ <a class="header-anchor" href="#我是如何開始踏上-bash-腳本編程之路的" aria-label="Permalink to “我是如何開始踏上 bash 腳本編程之路的？”">​</a></h1><blockquote><p>通過一些簡單的 Google 搜索，即使是編程入門者也可以嘗試編寫代碼將以往枯燥和冗長的任務自動化。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/computer_happy_sad_developer_programming.png?itok=5E3k_t_r" alt="How Google helped me learn bash scripting" title="How Google helped me learn bash scripting"></p><p>我前幾天寫了一個腳本。對於一些人來説，這句話聽起來沒什麼了不起的。而對於另一些人來説，這句話意義重大。要知道，我不是一個程序員，而是一個作家。</p><h3 id="我需要解決什麼" tabindex="-1">我需要解決什麼？ <a class="header-anchor" href="#我需要解決什麼" aria-label="Permalink to “我需要解決什麼？”">​</a></h3><p>我的問題相當簡單：我需要將工程文件進行分類。這些文件可以從一個網站 URL 以 .zip 的格式下載。當我正手工將它們拷貝到我的電腦桌面，並移動到一個已按照我文件分類的需要進行了結構化的目錄時，一位作家同事給我提了建議：<em>“不就是寫個腳本的事嗎？”</em></p><p>我心想：<em>“就寫個腳本？”</em>——説得好像這是世界上最容易做的事情一樣。</p><h3 id="google-是如何解救我的" tabindex="-1">Google 是如何解救我的？ <a class="header-anchor" href="#google-是如何解救我的" aria-label="Permalink to “Google 是如何解救我的？”">​</a></h3><p>同事的問題促使我思考，並且經過思考後，我進行了 Google 搜索。</p><p><strong>Linux 上使用的是什麼腳本編程語言？</strong></p><p>這是我第一個 Google 搜索的準則。也許很多人心裏會想：“她太笨了！”是的，我很笨。不過，這的確使我走上了一條解決問題的道路。最常見的搜索結果是 Bash 。嗯，我聽説過 Bash 。呃，我要分類的文件中有一個裏面就有 Bash，那無處不在的 <code>#!/bin/bash</code> 。我重新看了下那個文件，我知道它的用途，因為我需要將它分類。</p><p>這引導我進行了下一個 Google 搜索。</p><p><strong>如何從一個 URL 下載 zip 文件？</strong></p><p>那確實是我的基本任務。我有一個帶有 .zip 文件的 URL ，它包含有所有我需要分類的文件，所以我尋求萬能的 Google 的幫助。搜索到的精華內容和其它一些結果引導我使用 Curl 。但最重要的是：我不僅找到了 Curl ，其中一條置頂的搜索結果還展示了一個使用 Curl 去下載並解壓 .zip 文件的 Bash 腳本。這超出了我本來想尋求的答案，但那也使我意識到在 Google 搜索具體的請求可以得到我寫這個腳本需要的信息。所以，在這個收穫的推動下，我寫了最簡單的腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>curl http://rather.long.url | tar -xz -C my_directory --strip-components=1</span></span></code></pre></div><p>我迫不及待地運行看看。但我發現一個問題： URL 是會變的，根據我要訪問的文件的分組不同而不同。我有新的問題需要解決，這使我進行了下一輪搜索。</p><p><strong>參數如何傳遞給 Bash 腳本？</strong></p><p>我需要以不同的 URL 和不同的最終目錄來運行此腳本。 Google 向我展示瞭如何使用 <code>$1</code>、<code>$2</code> 等等來替換我在命令列中運行腳本時輸入的內容。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash myscript.sh http://rather.long.url my_directory</span></span></code></pre></div><p>這就好多了。一切如我所願，靈活，實用。最重要的是我只要輸入一條簡短的命令就可以節省 30 分鐘無聊的複製、粘貼工作。這個早上的時間花得值得。</p><p>然後我發現還有一個問題：我很健忘，並且我知道我幾個月才運行一次這個腳本。這留給我兩個疑問：</p><ul><li>我要如何記得運行腳本時輸入什麼（URL 先，還是目錄先）？</li><li>如果我被貨車撞了，其它作家如何知道該怎樣運行我的腳本？</li></ul><p>我需要一個使用説明 —— 如果我使用不正確，則腳本會提示。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>usage: bash yaml-fetch.sh &lt;&#39;snapshot_url&#39;&gt; &lt;directory&gt;</span></span></code></pre></div><p>否則，則直接運行腳本。我的下一個搜索是：</p><p><strong>如何在 Bash 腳本里使用 “if/then/else”?</strong></p><p>幸運的是，我已經知道編程中 <code>if/then/else</code> 的存在。我只要找出如何使用它的方法。在這個過程中，我也學到了如何在 Bash 腳本里使用 <code>echo</code> 打印。我的最終成果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>URL=$1</span></span>
<span class="line"><span>DIRECTORY=$2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ $# -eq 0 ];</span></span>
<span class="line"><span> then</span></span>
<span class="line"><span> echo &quot;usage: bash yaml-fetch.sh &lt;&#39;snapshot_url&#39;&gt; &lt;directory&gt;&quot;.</span></span>
<span class="line"><span> else</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 如果目錄不存在則創建它</span></span>
<span class="line"><span> echo &#39;create directory&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span> mkdir $DIRECTORY</span></span>
<span class="line"><span></span></span>
<span class="line"><span> # 下載並解壓 yaml 文件</span></span>
<span class="line"><span> echo &#39;fetch and untar the yaml files&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span> curl $URL | tar -xz -C $DIRECTORY --strip-components=1</span></span>
<span class="line"><span>fi</span></span></code></pre></div><h3 id="google-和腳本編程如何顛覆我的世界" tabindex="-1">Google 和腳本編程如何顛覆我的世界？ <a class="header-anchor" href="#google-和腳本編程如何顛覆我的世界" aria-label="Permalink to “Google 和腳本編程如何顛覆我的世界？”">​</a></h3><p>好吧，這稍微有點誇大，不過現在是 21 世紀，學習新東西（特別是稍微簡單的東西）比以前簡單多了。我所學到的（除了如何寫一個簡短的、自動分類的 Bash 腳本之外）是如果我有疑問，那麼有很大可能性是其它人在之前也有過相同的疑問。當我困惑時，我可以問下一個問題，再下一個問題。最後，我不僅擁有了腳本，還擁有了可以一直擁有並可以簡化其它任務的新技能，這是我之前所沒有的。</p><p>別止步於第一個腳本（或者編程的第一步）。這是一個技能，和其它的技能並無不同，有大量的信息可以在這一路上幫助你。你無需閲讀大量的書或參加一個月的課程。你可以像嬰兒學步那樣簡單地開始寫腳本，然後掌握技能並建立自信。人們總有寫成千上萬行代碼的需求，並對它進行分支、合併、修復錯誤。但是，通過簡單的腳本或其它方式來自動化、簡單化任務的需求也一樣強烈。這樣的一個小腳本和小小的自信就能夠讓你啓程腳本編程之路。</p><p>（題圖： opensource.com）</p><hr><p>作者簡介：</p><p>Sandra McCann 是一位 Linux 和開源技術的倡導者。她是一位軟件開發者、學習資源內容架構師、內容創作者。Sandra McCann 目前是位於韋斯特福德馬薩諸塞州的紅帽公司的內容創作者，專注於 OpenStack 和 NFV 技術。</p><hr>`,36)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/17/5/how-i-learned-bash-scripting"},{default:p(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/17/5/how-i-learned-bash-scripting",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/sandra-mccann"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra McCann",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),e(n,{href:"https://github.com/xllc"},{default:p(()=>[...s[3]||(s[3]=[a("xllc",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const x=i(d,[["render",g]]);export{y as __pageData,x as default};
